/* ==UserStyle==
@name         Purple GIF Full Transparency Theme
@namespace    stylish-theme
@version      1.3
@description  Purple theme with GIF background fully visible behind all content
==/UserStyle== */

/* Full-page GIF background */
html::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -9999;
    background: url("https://i.pinimg.com/originals/dc/23/2c/dc232c2a3fbdb1f0d4d21a2447403bd3.gif") no-repeat center center fixed;
    background-size: cover;
    filter: brightness(0.5) blur(2px); /* dim and slightly blur GIF for readability */
}

/* Make page background transparent */
body, html {
    background: transparent !important;
    color: #e0d7f2 !important;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
}

/* Make all main containers semi-transparent */
div, section, article, header, footer, main, aside {
    background: rgba(50, 0, 75, 0.4) !important;
    border-radius: 12px !important;
    padding: 6px !important;
    margin: 4px !important;
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    background: rgba(114,9,183,0.7) !important;
    color: #ffffff !important;
    border: 1px solid #f72585 !important;
    border-radius: 6px !important;
    transition: 0.3s all;
}
button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background: rgba(247,37,133,0.7) !important;
    border-color: #3a0ca3 !important;
}

/* Input fields */
input, textarea, select {
    background: rgba(50, 0, 75, 0.3) !important;
    color: #ffffff !important;
    border: 1px solid #7209b7 !important;
    border-radius: 6px !important;
}

/* Links */
a {
    color: #f72585 !important;
    text-decoration: none !important;
}
a:hover {
    color: #7209b7 !important;
    text-decoration: underline !important;
}

/* Headers */
h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 12px;
}
::-webkit-scrollbar-track {
    background: rgba(26,10,58,0.6);
    border-radius: 6px;
}
::-webkit-scrollbar-thumb {
    background: rgba(114,9,183,0.7);
    border-radius: 6px;
}
::-webkit-scrollbar-thumb:hover {
    background: rgba(247,37,133,0.7);
}
